    <script>document.addEventListener('DOMContentLoaded',()=>{const duration=document.querySelector('[data-live-shift-duration]');const pay=document.querySelector('[data-live-shift-pay]');const start=Number(duration?.dataset.startMs||0);const daily=Number(pay?.dataset.dailyRate||0);if(!start)return;const refresh=()=>{const minutes=Math.max(0,Math.floor((Date.now()-start)/60000));duration.textContent=Math.floor(minutes/60)+'h '+(minutes%60)+'m';pay.textContent='₱'+(daily*minutes/480).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2});};refresh();setInterval(refresh,15000);});</script>
    <script>document.addEventListener('DOMContentLoaded',()=>{const buttons=[...document.querySelectorAll('[data-driver-attendance-mode-button]')],panels=[...document.querySelectorAll('[data-driver-attendance-mode-panel]')],img=document.querySelector('[data-driver-attendance-qr]'),status=document.querySelector('[data-driver-qr-status]'),label=document.querySelector('[data-driver-qr-countdown]'),base=img?.dataset.qrBase,attendance=document.querySelector('[data-driver-today-attendance]');let timer=null;const refresh=async()=>{if(!img||!status||!base)return;status.textContent='Generating a fresh one-use QR…';try{const response=await fetch(base+'?t='+Date.now(),{credentials:'same-origin',headers:{Accept:'application/json'}});const payload=await response.json();if(!response.ok||payload.success===false)throw new Error(payload.message||'Could not issue your QR.');img.src=payload.qr_data_uri;img.classList.remove('hidden');label.textContent=payload.action+' QR · refreshes every 20 seconds';status.textContent='Ready for Logistics to scan · this code expires after 20 seconds.';if(attendance&&payload.today_attendance){const today=payload.today_attendance;const badge=attendance.querySelector('[data-today-status]');badge.textContent=today.status;badge.className='mt-1 block text-lg '+(today.status==='ABSENT'?'text-red-700':today.status==='ON SHIFT'?'text-primary':'text-emerald-700');attendance.querySelector('[data-today-details]').textContent=today.hours+'h / 8h · estimated ₱'+Number(today.pay_estimate).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2});}}catch(error){img.classList.add('hidden');status.textContent=error.message||'Could not issue your QR. Check your account status with Logistics.';}};const show=(mode)=>{for(const button of buttons){const selected=button.dataset.driverAttendanceModeButton===mode;button.setAttribute('aria-pressed',selected?'true':'false');button.classList.toggle('bg-primary',selected);button.classList.toggle('text-white',selected);button.classList.toggle('text-ink',!selected);}for(const panel of panels)panel.hidden=panel.dataset.driverAttendanceModePanel!==mode;if(mode==='qr'){const stop=document.querySelector('[data-attendance-qr-scanner] [data-attendance-stop]');if(stop&&!stop.classList.contains('hidden'))stop.click();void refresh();if(!timer)timer=setInterval(()=>void refresh(),19500);}else{clearInterval(timer);timer=null;}};for(const button of buttons)button.addEventListener('click',()=>show(button.dataset.driverAttendanceModeButton));show('scanner');});</script>
